-- Execute inside BEGIN/ROLLBACK with meadow-production-commerce.sql.
create temporary table meadow194_checks(name text,passed boolean);
do $$
declare u uuid:=gen_random_uuid(); request_id uuid:=gen_random_uuid(); rid uuid; result jsonb;
 n int; blocked boolean; nonce uuid; account text; username text:='qa_'||substr(replace(gen_random_uuid()::text,'-',''),1,12);
begin
 insert into auth.users(id,instance_id,email,role,aud,is_anonymous) values(u,'00000000-0000-0000-0000-000000000000','qa-'||u::text||'@players.sponsorsorter.com','authenticated','authenticated',true);
 insert into public.meadow_market_profiles(user_id,friend_code,display_name) values(u,'QA-'||substr(u::text,1,8),'Rollback-only QA');
 insert into public.meadow_market_accounts(username,user_id,ready) values(username,u,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 result:=public.meadow_market_commerce_status();
 if (result->>'test_access')::boolean or (result->>'payments_enabled')::boolean then raise exception 'Public account gained test/store access';end if;
 blocked:=false;begin perform public.meadow_market_play_service('purchase',jsonb_build_object('id',gen_random_uuid(),'sku','pocket_gems'));exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Public free pack accepted';end if;
 blocked:=false;begin perform public.meadow_market_reward_round('start',jsonb_build_object('id',gen_random_uuid(),'game','ad'));exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Public fake ad accepted';end if;
 insert into meadow194_checks values('public free-pack and fake-ad denial',true);
 blocked:=false;begin perform public.meadow_market_support_grant(request_id,u,20,30,3,true,'Rollback-only QA');exception when insufficient_privilege then blocked:=true;end;
 if not blocked or has_function_privilege('authenticated','public.meadow_market_support_grant(uuid,uuid,integer,integer,integer,boolean,text)','EXECUTE') then raise exception 'Player can grant rewards';end if;
 insert into meadow194_checks values('backend-only grants and purchase delivery',not has_function_privilege('authenticated','public.meadow_market_deliver_store_purchase(uuid,text,text,text,boolean)','EXECUTE'));
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 blocked:=false;begin perform public.meadow_market_deliver_store_purchase(u,'mm_pocket_gems',repeat('a',64),'test',true);exception when others then if sqlerrm='Store not open' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Closed store accepted payment';end if;
 update meadow_private.commerce_config set payments_enabled=true,production_ready=true,ads_enabled=true where id;
 update meadow_private.store_products set enabled=true;
 result:=public.meadow_market_deliver_store_purchase(u,'mm_pocket_gems',repeat('a',64),'test',true);
 result:=public.meadow_market_deliver_store_purchase(u,'mm_pocket_gems',repeat('a',64),'test',true);
 select gems into n from public.meadow_market_wallets where user_id=u;
 if n<>100 or not (result->>'duplicate')::boolean then raise exception 'Purchase credited twice';end if;
 blocked:=false;begin perform public.meadow_market_deliver_store_purchase(gen_random_uuid(),'mm_pocket_gems',repeat('a',64),'test',true);exception when others then if sqlerrm like 'Purchase belongs%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Purchase crossed accounts';end if;
 insert into meadow194_checks values('purchase replay and cross-account isolation',true);
 rid:=public.meadow_market_support_grant(request_id,u,20,30,3,true,'Rollback-only QA');
 if public.meadow_market_support_grant(request_id,u,20,30,3,true,'Rollback-only QA')<>rid then raise exception 'Grant receipt changed';end if;
 select gems into n from public.meadow_market_wallets where user_id=u;if n<>120 then raise exception 'Grant credited twice';end if;
 blocked:=false;begin perform public.meadow_market_support_grant(request_id,u,99,30,3,true,'Rollback-only QA');exception when others then if sqlerrm='Grant request reused' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Grant request body mutable';end if;
 insert into meadow194_checks values('audited grant replay and immutable request',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 nonce:=(public.meadow_market_start_ad_reward()->>'nonce')::uuid;
 account:=encode(sha256(convert_to('meadow-markets:'||u::text,'UTF8')),'hex');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.meadow_market_finish_ad_reward(nonce,account,'qa-transaction-194',clock_timestamp());
 perform public.meadow_market_finish_ad_reward(nonce,account,'qa-transaction-194',clock_timestamp());
 select gems into n from public.meadow_market_wallets where user_id=u;if n<>125 then raise exception 'Ad reward duplicated';end if;
 blocked:=false;begin perform public.meadow_market_finish_ad_reward(nonce,'wrong-account','qa-transaction-194',clock_timestamp());exception when others then if sqlerrm='Ad account mismatch' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Ad account mismatch accepted';end if;
 insert into meadow194_checks values('ad nonce/account binding and one-use delivery',true);
 perform public.meadow_market_revoke_store_purchase(repeat('a',64));
 perform public.meadow_market_revoke_store_purchase(repeat('a',64));
 select gems into n from public.meadow_market_wallets where user_id=u;if n<>25 then raise exception 'Refund duplicated or wrong amount';end if;
 blocked:=false;begin perform public.meadow_market_deliver_store_purchase(u,'mm_pocket_gems',repeat('b',64),'test-2',true);exception when others then if sqlerrm like 'Purchases need a support review%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Refund purchase loop accepted';end if;
 insert into meadow194_checks values('refund revocation, replay and repeat-purchase hold',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.meadow_market_account_deletion('request');
 if not (public.meadow_market_account_deletion('status')->>'pending')::boolean then raise exception 'Deletion not queued';end if;
 perform public.meadow_market_account_deletion('cancel');
 if (public.meadow_market_account_deletion('status')->>'pending')::boolean then raise exception 'Deletion not cancelled';end if;
 perform public.meadow_market_account_deletion('request');
 update meadow_private.account_deletions set execute_after=now()-interval '1 minute' where user_id=u;
 insert into meadow_private.farm_backups(user_id,revision,save_data) values(u,0,'{}');
 insert into public.meadow_market_saves(user_id,save_data) values(u,'{"version":1,"coins":500,"farms":{}}');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform meadow_private.erase_due_game_accounts();
 if exists(select 1 from public.meadow_market_saves where user_id=u) or exists(select 1 from public.meadow_market_accounts where user_id=u) or exists(select 1 from meadow_private.farm_backups where user_id=u) or exists(select 1 from public.meadow_market_profiles where user_id=u) then raise exception 'Game data survived deletion';end if;
 if not exists(select 1 from auth.users where id=u) then raise exception 'Shared Auth principal was touched';end if;
 blocked:=false;begin insert into public.meadow_market_profiles(user_id,friend_code,display_name) values(u,'QA-'||substr(u::text,1,8),'Resurrected');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Old session resurrected deleted game data';end if;
 insert into meadow194_checks values('deletion request/cancel/purge and other-app isolation',true);
end $$;
select jsonb_agg(jsonb_build_object('check',name,'passed',passed)) as checks from meadow194_checks;
